static int32_t  XLXCXP_getRegInfo(DRV_FpgaRegId regId, uint32_t *pAddr, uint32_t *pBitMask, uint32_t *pPosBit);

// Wired into ops table:
DRV_FPGA_OP_DEFINE(xlx_cxpV1) = {
    .writeRegById   = XLXCXP_writeRegById,
    .readRegById    = XLXCXP_readRegById,
    ...
};
```

The `DRV_FPGA_OP_DEFINE/DECLARE/ADDRESS` macros (from `fpga_priv.h`) expand to `g_fpgaxxx_ops` references. The main `drv_fpga.c` dispatches through `s_pFpgaDrvOps` which is resolved by name at init time.

---

### 4. Register Access Pattern: `FPGA_GET_REG_VAL` / `FPGA_SET_REG_VAL`

**Yes, these are the primary convenience macros.** Defined in `drv_fpgaReg.h` at lines 2066-2067:

```c
#define FPGA_GET_REG_VAL(_REGID)       DRV_fpgaReadRegById(_REGID)
#define FPGA_SET_REG_VAL(_REGID, _VAL) DRV_fpgaWriteRegById(_REGID, _VAL)
```

These are the high-level-by-ID access. Under the hood, the implementation (visible in both `XLXCXP_writeRegById` and `XLXCXPLine_writeRegById`) uses the three-field lookup:

```c
addr     = s_xlxCXPRegTbl[regId].addr32;
pos      = s_xlxCXPRegTbl[regId].posBit;
bitMask  = s_xlxCXPRegTbl[regId].bitMask;

// For write -- full-word fast path:
if ((0xFFFFFFFF == bitMask) && (0 == pos))
{
    *((volatile uint32_t *)(unsigned long)addr) = regVal;
}
else  // Read-modify-write for bit fields:
{
    *((volatile uint32_t *)(unsigned long)addr) =
        (*((volatile uint32_t *)(unsigned long)addr) & (~(bitMask << pos)))
        | ((regVal & bitMask) << pos);
}

// For read:
return ((*((volatile uint32_t *)(unsigned long)addr)) & (bitMask << pos)) >> pos;
```

There are additionally **by-address** access macros (also in `drv_fpgaReg.h`, lines 2078-2103):

```c
// Direct MMIO by base address + offset (offset shifted >> 2):
#define IORD(baseRegAddr, offset)     (*((volatile uint32_t *)(unsigned long)((baseRegAddr) + (((offset) >> 2) << 2))))
#define IOWR(baseRegAddr, offset, data) (*((volatile uint32_t *)(unsigned long)((baseRegAddr) + (((offset) >> 2) << 2))) = (uint32_t)(data))

// PIO set/clear bits:
#define IOWR_PIO_SET_BITS(baseRegAddr,data)   IOWR(baseRegAddr, 0x10, data)
#define IOWR_PIO_CLEAR_BITS(baseRegAddr,data) IOWR(baseRegAddr, 0x14, data)
#define IORD_PIO_DATA(baseRegAddr)            IORD(baseRegAddr, 0)

// Simple MMIO (no offset):
#define MM_READ(regAddr)    (*((volatile uint32_t *)(unsigned long)(regAddr)))
#define MM_WRITE(regAddr,value) (*((volatile uint32_t *)(unsigned long)(regAddr)) = (uint32_t)(value))
```

And **struct-based** register field access macros (lines 2087-2099):

```c
#define FPGA_STU_GET_REG32_VAL(_REG)       (*((volatile uint32_t *)(&(_REG))))
#define FPGA_STU_SET_REG32_VAL(_REG, _VAL) (*((volatile uint32_t *)(&(_REG))) = (uint32_t)(_VAL))

// Bitfield get/set using _POS and _MSK conventions:
#define FPGA_STU_GET_REG32_FIELD(_REG, _FIELD) \
    ((FPGA_STU_GET_REG32_VAL(_REG) & _FIELD##_MSK) >> _FIELD##_POS)

#define FPGA_STU_SET_REG32_FIELD(_REG, _FIELD, _DATA) \
    FPGA_STU_SET_REG32_VAL(_REG, (FPGA_STU_GET_REG32_VAL(_REG) & (~_FIELD##_MSK)) | \
        (((uint32_t)(_DATA) << _FIELD##_POS) & (_FIELD##_MSK)))
```

---

### 5. Bit Operation Patterns

The bit operations are **not done via separate utility macros** -- they are inlined directly in the register access functions and in the `FPGA_STU_*` macros. The patterns used are:

| Operation | Pattern | Example |
|-----------|---------|---------|
| Mask + shift (read) | `(regVal & (mask << pos)) >> pos` | `((*((volatile uint32_t *)addr)) & (bitMask << pos)) >> pos` |
| Clear + set (write) | `(oldVal & ~(mask << pos)) \| ((newVal & mask) << pos)` | `(*(addr) & (~(bitMask << pos))) \| ((regVal & bitMask) << pos)` |
| Full word write | Direct write when `mask==0xFFFFFFFF && pos==0` | `*((volatile uint32_t *)addr) = regVal` |
| Struct field get | `(_FIELD##_MSK)` and `(_FIELD##_POS)` token-pasting | `FPGA_STU_GET_REG32_FIELD(reg, SOME_FIELD)` assumes `SOME_FIELD_MSK` and `SOME_FIELD_POS` |
| PIO set/clear | Writes to offset 0x10/0x14 from base | `IOWR_PIO_SET_BITS(base, data)` |

---

### Summary of Architecture

The system uses a **three-layer** architecture:

1. **Register ID enum** (`DRV_FpgaRegId` in `drv_fpgaReg.h`): Platform-independent register identifiers (~1000 entries). Each platform implements only the registers it needs.

2. **Platform-specific register tables** (`s_xlxCXPRegTbl[]`, `s_xlxCxpLineRegTbl[]`, etc.): Each entry is `{addr32, posBit, bitMask}` allowing arbitrary bit-fields within 32-bit MMIO words. Designated initializers (`[FPGA_RID_xxx] =`) ensure sparse, readable mapping.

3. **Function-pointer dispatch** (`DRV_FpgaOps` in `fpga_priv.h`): The `drv_fpga.c` layer selects the platform ops at init time by name match, then delegates all `DRV_fpgaReadRegById`/`DRV_fpgaWriteRegById` calls through the ops table.

