    uint32_t (*readRegByAddr)(uint32_t regAddr32, int32_t offset32);
    int32_t  (*getRegInfo)(DRV_FpgaRegId regId, uint32_t *pAddr, uint32_t *pBitMask, uint32_t *pPosBit);
